groups.query:
SELECT DISTINCT ?item ?itemLabel ?answer ?answerLabel ?reference WHERE {
 { SELECT DISTINCT ?item ?itemLabel ?answer WHERE {
 ?item wdt:P31 wd:Q11424; wdt:P57 ?answer.
 ?item rdfs:label ?itemLabel FILTER(LANG(?itemLabel)="pt")
 } LIMIT 3600 }
 FILTER NOT EXISTS { ?item wdt:P57 ?other FILTER(?other != ?answer) }
 ?item p:P57 ?claim. ?claim ps:P57 ?answer; prov:wasDerivedFrom ?ref.
 ?ref (pr:P854|pr:P248) ?reference.
 SERVICE wikibase:label { bd:serviceParam wikibase:language "pt,mul,en". }
 }
